def solve_exact(n_a, n_b, d):
    # A = {1, ..., n_a}, B = {k+1, ..., k+n_b}
    # We want to maximize sum_{i=1 to n_a} count(i, k)
    # count(i, k) = number of j in {1, ..., n_b} such that |i - (k+j)| <= d
    # i-k-d <= j <= i-k+d
    # So j is in [max(1, i-k-d), min(n_b, i-k+d)]
    max_k = 0
    for k in range(-n_a - n_b, n_a + n_b):
        current_k = 0
        for i in range(1, n_a + 1):
            low = max(1, i - k - d)
            high = min(n_b, i - k + d)
            if low <= high:
                current_k += (high - low + 1)
        if current_k > max_k:
            max_k = current_k
    return max_k

print(solve_exact(2000, 2016, 1000))

