            high = min(n_b, i - k + d)
            if low <= high:
                current_k += (high - low + 1)
        if current_k > max_k:
            max_k = current_k
            best_k = k

    # Print counts for best_k
    counts = []
    for i in range(1, n_a + 1):
        low = max(1, i - best_k - d)
        high = min(n_b, i - best_k + d)
