def get_diff_counts_efficient(na, nb):
    # m in 1..na, n in 1..nb. d = m-n.
    # d ranges from 1-nb to na-1.
    # d = m-n => m = n+d.
    # 1 <= n+d <= na and 1 <= n <= nb.
    # So max(1, 1-d) <= n <= min(nb, na-d).
    # Number of n's is max(0, min(nb, na-d) - max(1, 1-d) + 1).
    counts = {}
    for d in range(1 - nb, na):
        count = max(0, min(nb, na - d) - max(1, 1 - d) + 1)
        if count > 0:
            counts[d] = count
    return counts

def solve_diffs(na, nb, nc):
    counts = get_diff_counts_efficient(na, nb)
    sorted_counts = sorted(counts.values(), reverse=True)
    return sum(sorted_counts[:nc])

print(solve_diffs(2000, 2016, 2020))

def count_pairs(na, nb, d):
    count = 0
    for m in range(1, na + 1):
        # |m-n| <= d  =>  m-d <= n <= m+d
        low = max(1, m - d)
        high = min(nb, m + d)
        if low <= high:
            count += (high - low + 1)
    return count

print(count_pairs(2000, 2016, 1000))
